package co.kr.badara.dolswevoice;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private final int GREEN=Color.rgb(40,83,69),MUTED=Color.rgb(116,131,122),BG=Color.rgb(246,247,242);private LinearLayout root,body,tabs;private TextView live,homeSummary,updateSummary;private EditText wifiField;private AppUpdates updates;private Config cfg;private String page="home",pendingMode="wake";private final ExecutorService io=Executors.newSingleThreadExecutor();private final Map<String,EditText> aliasFields=new LinkedHashMap<>();private final Map<String,EditText> lockCodeFields=new LinkedHashMap<>();private final Map<String,CheckBox> lockCodeDeleteFields=new LinkedHashMap<>();private boolean busy=false;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(live!=null)live.setText(i.getStringExtra("text"));}};
 public void onCreate(Bundle b){super.onCreate(b);cfg=new Config(this);updates=new AppUpdates(this);updates.onStatus(this::refreshUpdate);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);show("home");}
 protected void onStart(){super.onStart();if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,new IntentFilter(VoiceService.EVENT),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,new IntentFilter(VoiceService.EVENT));}protected void onStop(){super.onStop();unregisterReceiver(receiver);}protected void onResume(){super.onResume();if(updates!=null)updates.resume(cfg.p.getBoolean("autoUpdate",true));refreshHome();refreshUpdate();}protected void onPause(){if(updates!=null)updates.pause();super.onPause();}protected void onDestroy(){if(updates!=null)updates.close();io.shutdown();super.onDestroy();}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);v.setPadding(0,dp(6),0,dp(6));return v;}
 private Button button(String s,Runnable action,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(primary?Color.WHITE:GREEN);b.setBackground(shape(primary?GREEN:Color.WHITE,12));b.setPadding(dp(12),dp(8),dp(12),dp(8));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.setMargins(0,dp(8),0,dp(4));b.setLayoutParams(lp);b.setOnClickListener(v->action.run());return b;}
 private EditText field(LinearLayout parent,String label,String value,String hint,boolean secret){parent.addView(text(label,12,MUTED,false));EditText e=new EditText(this);e.setSingleLine(!label.equals("호출어"));e.setText(value);e.setHint(hint);e.setTextSize(15);e.setTextColor(GREEN);e.setPadding(dp(12),dp(12),dp(12),dp(12));e.setBackground(shape(Color.WHITE,10));if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);parent.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(18),dp(14),dp(18),dp(14));c.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(10));body.addView(c,lp);return c;}
 private void show(String p){page=p;live=null;homeSummary=null;updateSummary=null;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(20),dp(12),dp(20),dp(12));root.setFitsSystemWindows(true);setContentView(root);root.addView(text("DOLSWE  /  HOME ASSISTANT",10,MUTED,true));root.addView(text("돌쇠 음성비서",26,GREEN,true));tabs=new LinearLayout(this);for(String[] t:new String[][]{{"home","음성"},{"devices","장치 별칭"},{"settings","설정"}}){Button b=button(t[1],()->show(t[0]),p.equals(t[0]));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(42),1);lp.setMargins(dp(3),dp(6),dp(3),dp(10));tabs.addView(b,lp);}root.addView(tabs);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(6),0,dp(24));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(p.equals("settings"))settings();else if(p.equals("devices"))devices();else home();}
 private void home(){LinearLayout c=card();c.addView(text("말로 부르는 우리 집",20,GREEN,true));c.addView(text(cfg.wakes(),24,GREEN,true));live=text(VoiceService.running?VoiceService.status:cfg.last(),15,MUTED,false);c.addView(live);c.addView(text("‘이모님 거실 불’처럼 장치 이름만 말하면 현재 상태를 반대로 바꿉니다. 응답 후 다음 명령을 이어 말할 수 있어요. 음성은 휴대폰에서 처리합니다.",12,MUTED,false));c.addView(text("집 와이파이에서만 음성인식 · "+(cfg.ssid().isEmpty()?"설정 필요":cfg.ssid()),12,MUTED,false));body.addView(button("호출 대기 시작",()->start("wake"),true));body.addView(button("마이크로 명령",()->start("command"),false));body.addView(button("호출어 인식 테스트",()->start("test"),false));body.addView(button("대기 중지",()->{stopService(new Intent(this,VoiceService.class));if(live!=null)live.setText("대기 중지");},false));LinearLayout guide=card();guide.addView(text(cfg.dry()?"현재 시험 모드 · 실제 장치 조작 안 함":"현재 실제 제어 모드",14,GREEN,true));guide.addView(text("① 설정에 HA 주소·토큰·레이블 입력\n② 장치 별칭에서 목록 불러오기\n③ 이름을 연결하고 저장\n④ 설정에서 집 와이파이 저장\n⑤ 호출 대기 시작\n\n예: ‘돌쇠야, 거실 불 켜줘’\n‘이모님’ → 응답 후 ‘안방 선풍기 꺼줘’",13,MUTED,false));guide.addView(text("SenseVoice INT8 (한국어 검증판) · 한국어 / Silero VAD\n화면이 꺼져도 동작하도록 알림과 마이크 권한을 허용하세요. 강제 종료·재부팅 후에는 앱에서 다시 시작합니다.",12,MUTED,false));}
 private void settings(){EditText base=field(body,"HA 주소",cfg.base(),"https://ha.example.com",false);EditText label=field(body,"HA 엔티티에 지정한 레이블 이름",cfg.label(),"엔티티의 레이블 이름과 똑같이 입력",false);EditText token=field(body,"HA 장기 액세스 토큰","","처음 연결할 때 입력 / 빈 칸이면 기존 토큰 유지",true);body.addView(text("토큰은 HA 프로필 → 보안 → 장기 액세스 토큰에서 직접 만들 수 있습니다. 이 앱은 토큰을 휴대폰 보안 저장소로 암호화해 저장합니다.",12,MUTED,false));EditText wakes=field(body,"호출어",cfg.wakes(),"돌쇠야, 이모님",false);body.addView(text("쉼표로 나눠 여러 개를 입력하세요. 문장 앞에서 호출어가 일치할 때 반응합니다. ‘호출어 인식 테스트’에서 실제 인식 결과를 확인하세요.",12,MUTED,false));wifiField=field(body,"집 와이파이 이름 (SSID)",cfg.ssid(),"연결된 집 와이파이를 아래 버튼으로 선택",false);body.addView(button("현재 와이파이를 집으로 지정",this::fillCurrentWifi,false));homeSummary=text("",12,MUTED,false);body.addView(homeSummary);refreshHome();body.addView(text("지정한 와이파이에 연결돼 있을 때만 음성인식이 켜집니다. 연결을 끊으면 마이크와 음성 모델을 멈추고, 다시 연결되면 대기를 재개합니다. GPS 위치는 수집하지 않습니다. 안드로이드에서 와이파이 이름을 읽으려면 정확한 위치 권한과 휴대폰 위치 기능이 필요합니다.",12,MUTED,false));body.addView(button("휴대폰 위치 기능 설정",()->startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)),false));Switch continuous=new Switch(this);continuous.setText("응답 후 연속 말하기");continuous.setChecked(cfg.continuous());body.addView(continuous);EditText follow=field(body,"추가 명령 대기 시간 (5~60초)",Integer.toString(cfg.followSeconds()),"20",false);follow.setInputType(InputType.TYPE_CLASS_NUMBER);body.addView(text("처음에 호출어를 말하고, 응답이 끝나면 호출어 없이 다음 장치를 말하세요. 예: ‘이모님 거실 불 켜줘’ → 응답 → ‘안방 선풍기 꺼줘’. ‘그만’으로 끝냅니다. 대기 시간이 지나면 호출어가 다시 필요합니다.",12,MUTED,false));Switch quiet=new Switch(this);quiet.setText("야간 음성인식 금지 시간 사용");quiet.setChecked(cfg.quietEnabled());body.addView(quiet);final int[] quietTimes={cfg.quietStart(),cfg.quietEnd()};Button quietStart=button("금지 시작  "+QuietHours.format(quietTimes[0]),()->{},false),quietEnd=button("금지 종료  "+QuietHours.format(quietTimes[1]),()->{},false);quietStart.setOnClickListener(v->new TimePickerDialog(this,(view,h,m)->{quietTimes[0]=h*60+m;quietStart.setText("금지 시작  "+QuietHours.format(quietTimes[0]));},quietTimes[0]/60,quietTimes[0]%60,true).show());quietEnd.setOnClickListener(v->new TimePickerDialog(this,(view,h,m)->{quietTimes[1]=h*60+m;quietEnd.setText("금지 종료  "+QuietHours.format(quietTimes[1]));},quietTimes[1]/60,quietTimes[1]%60,true).show());quietStart.setEnabled(quiet.isChecked());quietEnd.setEnabled(quiet.isChecked());quiet.setOnCheckedChangeListener((v,on)->{quietStart.setEnabled(on);quietEnd.setEnabled(on);});body.addView(quietStart);body.addView(quietEnd);body.addView(text("매일 반복합니다. 예: 22:00~07:00. 금지 시간에는 호출어·명령·인식 테스트를 모두 멈추고, 종료 후 집 와이파이에 연결되어 있으면 대기를 재개합니다. 휴대폰의 현재 시간대를 따르며, 절전 상태에서는 재개가 늦어질 수 있습니다.",12,MUTED,false));Switch autoUpdate=new Switch(this);autoUpdate.setText("앱 실행·복귀 시 업데이트 확인·다운로드");autoUpdate.setChecked(cfg.p.getBoolean("autoUpdate",true));autoUpdate.setPadding(0,dp(12),0,dp(12));body.addView(autoUpdate);body.addView(button("지금 업데이트 확인",()->updates.check(true),false));updateSummary=text(updates.status(),12,MUTED,false);body.addView(updateSummary);body.addView(text("새 버전은 자동으로 다운로드하고 설치 화면을 엽니다. 최종 설치는 안드로이드에서 확인해주세요.",12,MUTED,false));Switch unlock=new Switch(this);unlock.setText("도어록 음성 잠금 해제 허용");unlock.setChecked(cfg.p.getBoolean("allowLockUnlock",false));unlock.setPadding(0,dp(12),0,dp(12));body.addView(unlock);body.addView(text("도어록: 켜·닫아는 잠금, 꺼·열어는 잠금 해제입니다. 잠금 해제는 이 옵션을 켜야 실행됩니다.",12,MUTED,false));Switch near=new Switch(this);near.setText("호출어 발음 보정 (오반응 시 끄기)");near.setChecked(cfg.p.getBoolean("nearWake",true));near.setPadding(0,dp(12),0,dp(12));body.addView(near);Switch dry=new Switch(this);dry.setText("시험 모드 (실제 장치 조작 안 함)");dry.setChecked(cfg.dry());dry.setPadding(0,dp(12),0,dp(12));body.addView(dry);body.addView(button("연결 설정 저장",()->{try{String selected=wifiField.getText().toString();if(WifiPolicy.ssid(selected).isEmpty()||selected.length()>64)throw new Exception("집 와이파이 이름을 입력해주세요.");int seconds;try{seconds=Integer.parseInt(follow.getText().toString());}catch(Exception invalid){throw new Exception("추가 명령 대기 시간을 5~60초로 입력해주세요.");}if(seconds<5||seconds>60)throw new Exception("추가 명령 대기 시간을 5~60초로 입력해주세요.");if(quiet.isChecked()&&!QuietHours.valid(quietTimes[0],quietTimes[1]))throw new Exception("금지 시작과 종료 시간을 다르게 설정해주세요.");cfg.save(base.getText().toString(),label.getText().toString(),wakes.getText().toString(),token.getText().toString(),dry.isChecked());cfg.p.edit().putBoolean("nearWake",near.isChecked()).putString("homeSsid",WifiPolicy.ssid(selected)).putBoolean("continuous",continuous.isChecked()).putInt("followSeconds",seconds).putBoolean("quietEnabled",quiet.isChecked()).putInt("quietStart",quietTimes[0]).putInt("quietEnd",quietTimes[1]).putBoolean("autoUpdate",autoUpdate.isChecked()).putBoolean("allowLockUnlock",unlock.isChecked()).apply();stopService(new Intent(this,VoiceService.class));token.setText("");message("저장했습니다. 장치 목록을 불러오고 호출 대기를 다시 시작하세요.");}catch(Exception e){message(VoiceService.message(e));}},true));body.addView(button("배터리 제한 설정 열기",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))),false));body.addView(text("휴대폰 설정에서 배터리 사용을 ‘제한 없음’으로 선택하세요. 알림을 끄거나 앱을 강제 종료하면 호출 대기가 중단될 수 있습니다. 호출 대기는 일반 앱보다 배터리를 더 사용합니다.\n\n버전 1.2.3",12,MUTED,false));}
 private void devices(){body.addView(text("연동 레이블: "+(cfg.label().isEmpty()?"설정에서 먼저 입력":cfg.label()),15,GREEN,true));body.addView(text("해당 레이블의 항목만 표시합니다. 별칭은 쉼표로 8개까지 입력할 수 있습니다. 조명은 불·등·전등·조명을 바꿔 불러도 됩니다. 장치 이름만 말하면 현재 상태를 반대로 전환합니다. 버튼은 이름만 말해도 한 번 누르고, 센서는 상태를 읽습니다.",12,MUTED,false));body.addView(button(busy?"불러오는 중…":"HA 장치 목록 불러오기",this::sync,false));aliasFields.clear();lockCodeFields.clear();lockCodeDeleteFields.clear();JSONArray cache=cfg.cache();for(int i=0;i<cache.length();i++){JSONObject o=cache.optJSONObject(i);if(o==null)continue;LinearLayout c=card();String id=o.optString("id");c.addView(text(o.optString("name"),16,GREEN,true));c.addView(text(id+" · "+o.optString("state"),11,MUTED,false));EditText alias=field(c,"앱에서 부를 이름",cfg.alias(id),"예: 거실 불, 메인 조명",false);aliasFields.put(id,alias);if(id.startsWith("lock.")){EditText code=field(c,"도어록 코드 (필요한 기기만)","",cfg.hasLockCode(id)?"저장된 코드 있음 / 빈 칸이면 유지":"HA에서 요구하는 코드가 있으면 입력",true);lockCodeFields.put(id,code);if(cfg.hasLockCode(id)){CheckBox remove=new CheckBox(this);remove.setText("저장된 도어록 코드 삭제");c.addView(remove);lockCodeDeleteFields.put(id,remove);}c.addView(text("코드는 암호화해 저장하며 음성으로 읽거나 표시하지 않습니다.",11,MUTED,false));}}if(cache.length()==0)body.addView(text("목록이 비어 있으면 HA 레이블의 철자와 장치·엔티티에 레이블이 붙었는지 확인하세요.",13,MUTED,false));else body.addView(button("장치 별칭 저장",()->{try{JSONObject a=new JSONObject();for(Map.Entry<String,EditText> e:aliasFields.entrySet())a.put(e.getKey(),e.getValue().getText().toString().trim());Map<String,String> codes=new LinkedHashMap<>();for(Map.Entry<String,EditText> e:lockCodeFields.entrySet())codes.put(e.getKey(),e.getValue().getText().toString());Set<String> deletes=new HashSet<>();for(Map.Entry<String,CheckBox> e:lockCodeDeleteFields.entrySet())if(e.getValue().isChecked())deletes.add(e.getKey());cfg.saveDeviceSettings(a,codes,deletes);show("devices");message("별칭과 도어록 설정을 저장했습니다.");}catch(Exception e){message(VoiceService.message(e));}},true));}
 private void sync(){if(busy)return;busy=true;message("HA 레이블을 확인하고 있습니다…");io.execute(()->{try{List<HaClient.Entity> entities=cfg.client().list(cfg.label());cfg.cache(entities);runOnUiThread(()->{busy=false;show("devices");message(entities.size()+"개 항목을 불러왔습니다.");});}catch(Exception e){runOnUiThread(()->{busy=false;message(VoiceService.message(e));});}});}
 private void start(String mode){pendingMode=mode;try{
  if(cfg.ssid().isEmpty())throw new Exception("설정에서 집 와이파이 이름을 저장해주세요.");
  if(!mode.equals("test")){if(cfg.token().isEmpty()||cfg.label().isEmpty())throw new Exception("설정에서 HA 연결과 레이블을 먼저 저장해주세요.");if(cfg.targets().isEmpty())throw new Exception("장치 별칭을 하나 이상 저장해주세요.");}
  List<String> permissions=new ArrayList<>();if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){permissions.add(android.Manifest.permission.ACCESS_FINE_LOCATION);permissions.add(android.Manifest.permission.ACCESS_COARSE_LOCATION);}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)permissions.add(android.Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permissions.add(android.Manifest.permission.POST_NOTIFICATIONS);
  if(!permissions.isEmpty()){requestPermissions(permissions.toArray(new String[0]),7);return;}startForegroundService(new Intent(this,VoiceService.class).putExtra("mode",mode));if(live!=null)live.setText("집 와이파이 확인 중…");
 }catch(Exception e){message(VoiceService.message(e));}}
 private void fillCurrentWifi(){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},8);return;}String ssid=WifiGate.currentSsid(this);if(ssid.isEmpty()){message("집 와이파이 연결과 휴대폰 위치 기능을 확인해주세요.");return;}if(wifiField!=null){wifiField.setText(ssid);message("현재 와이파이를 입력했습니다. 연결 설정 저장을 눌러주세요.");}}
 public void onRequestPermissionsResult(int request,String[] p,int[] g){super.onRequestPermissionsResult(request,p,g);if(request==8){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)fillCurrentWifi();else message("와이파이 이름을 확인하려면 정확한 위치 권한을 허용해주세요.");return;}if(request==7&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){try{startForegroundService(new Intent(this,VoiceService.class).putExtra("mode",pendingMode));if(live!=null)live.setText("집 와이파이 확인 중…");}catch(Exception e){message(VoiceService.message(e));}}else if(request==7)message("마이크와 정확한 위치 권한을 확인해주세요. 위치 권한은 와이파이 이름 확인에만 사용합니다.");}
 private void refreshUpdate(){if(updateSummary!=null)updateSummary.setText(updates.status());}
 private void refreshHome(){if(homeSummary==null)return;String current=WifiGate.currentSsid(this);homeSummary.setText("현재 와이파이: "+(current.isEmpty()?"이름 확인 필요":current)+"\n저장된 집 와이파이: "+(cfg.ssid().isEmpty()?"미설정":cfg.ssid()));}
 private void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("확인",null).show();}
}
